import{_ as e,o as i,c as l,a2 as a}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"O4 订阅系统功能全量审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/O4-subscription.md","filePath":"audit/O4-subscription.md","lastUpdated":1792449669000}'),t={name:"audit/O4-subscription.md"};function r(d,o,c,n,s,u){return i(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="o4-订阅系统功能全量审计" tabindex="-1">O4 订阅系统功能全量审计 <a class="header-anchor" href="#o4-订阅系统功能全量审计" aria-label="Permalink to &quot;O4 订阅系统功能全量审计&quot;">​</a></h1><p><strong>审计日期</strong>: 2026-10-20 <strong>参考手册</strong>: <code>doc/guide/subscription.md</code><strong>审计员</strong>: O4-subscription</p><h2 id="审计范围" tabindex="-1">审计范围 <a class="header-anchor" href="#审计范围" aria-label="Permalink to &quot;审计范围&quot;">​</a></h2><p>对照手册，对订阅系统 8 大功能逐项核验：</p><ol><li>订阅 CRUD（创建、编辑、删除、复制）</li><li>订阅分配（按用户、按入站、按中转）</li><li>订阅渲染（Clash/Surge/SingBox/Loon/QX/Shadowrocket）</li><li>订阅规则（规则组）</li><li>订阅脚本（goja）</li><li>订阅签名（HMAC）</li><li>我的订阅（用户端）</li><li>处理流水线（过滤→改名→国旗→前缀→去重→排序）</li></ol><h2 id="发现问题" tabindex="-1">发现问题 <a class="header-anchor" href="#发现问题" aria-label="Permalink to &quot;发现问题&quot;">​</a></h2><h3 id="p1" tabindex="-1">P1 <a class="header-anchor" href="#p1" aria-label="Permalink to &quot;P1&quot;">​</a></h3><p><strong>O4-001：订阅预览不返回脚本错误，前端无法显示</strong></p><ul><li><strong>文件</strong>: <code>go-backend/internal/http/handler/subscription.go:733</code> (<code>subscriptionPreview</code>)</li><li><strong>手册</strong>: &quot;脚本执行失败不影响改名规则等其他步骤的结果&quot; 且 &quot;编辑器会显示错误&quot;</li><li><strong>实际</strong>: <code>subscriptionPreview</code> 调用 <code>kernel.ApplySubOptions</code>，脚本失败时错误被静默忽略（<code>sub_options.go:253</code> 的 <code>if scripted, err := ApplySubScript(...); err == nil</code>）。<code>SubScriptError</code> 函数存在（<code>sub_options.go:258</code>）但 preview 未调用。前端 <code>subscription.tsx</code> 也无脚本错误显示逻辑。</li><li><strong>复现</strong>: 在订阅编辑页输入死循环脚本 <code>function operator(n){while(true){}}</code>，点&quot;看看结果&quot;，无错误提示，节点列表正常返回（脚本被静默跳过）。</li><li><strong>影响</strong>: 用户无法得知脚本有误，误以为脚本生效。</li></ul><h3 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h3><p><strong>O4-002：TestLoonList/TestQXList 失败（测试维护债）</strong></p><ul><li><strong>文件</strong>: <code>go-backend/internal/kernel/share_clients_test.go:34,57</code></li><li><strong>原因</strong>: 测试硬编码期望 <code>sni=www.microsoft.com</code>，实际默认 SNI 已在 1.0.2 改为 <code>www.amd.com</code>（<code>kernel/model.go:160</code>）。</li><li><strong>复现</strong>: <code>go test -vet=off ./internal/kernel/ -run &quot;TestLoonList|TestQXList&quot;</code> → 2 FAIL。</li><li><strong>影响</strong>: 非功能 bug，但 CI 若跑此测试会红。</li></ul><p><strong>O4-003：订阅 HMAC 签名未绑定订阅 token</strong></p><ul><li><strong>文件</strong>: <code>go-backend/internal/http/handler/user_inbound.go:19</code></li><li><strong>实际</strong>: <code>subURLSig</code> 输入仅 <code>flvx-subsig-v1:{userID}</code>，同一用户的 sig 可复用于该用户有权限的任意订阅 token。</li><li><strong>风险</strong>: 低（token 128 位不可猜，且后端有二次权限过滤）。但不符合&quot;签名绑定资源&quot;的最佳实践。</li><li><strong>建议</strong>: 改为 <code>flvx-subsig-v1:{userID}:{token}</code>。</li></ul><p><strong>O4-004：手册与代码的流水线顺序描述不一致</strong></p><ul><li><strong>手册</strong>: &quot;过滤 → 改名 → 国旗 → 前缀 → 去重 → 排序&quot;</li><li><strong>代码</strong> (<code>sub_options.go:219-256</code>): 过滤 → 改名 → 国旗 → 去重 → 前缀 → 排序</li><li><strong>实际影响</strong>: 无（去重键为 host|port|protocol，不含名称，前缀不影响去重结果）。</li><li><strong>建议</strong>: 统一文档或代码注释，避免后续维护者误解。</li></ul><h3 id="p3" tabindex="-1">P3 <a class="header-anchor" href="#p3" aria-label="Permalink to &quot;P3&quot;">​</a></h3><p><strong>O4-005：<code>NormalizeRuleGroups</code> 未在保存时调用</strong></p><ul><li><strong>文件</strong>: <code>go-backend/internal/http/handler/subscription.go:61</code> (<code>normalize()</code>)</li><li><strong>实际</strong>: 非法 rule key 存入 DB，依赖渲染侧 <code>enabledRuleGroups</code> 的 fail-safe 过滤。</li><li><strong>影响</strong>: 低。数据卫生问题。</li></ul><h2 id="验证通过" tabindex="-1">验证通过 <a class="header-anchor" href="#验证通过" aria-label="Permalink to &quot;验证通过&quot;">​</a></h2><h3 id="_1-订阅-crud-✅" tabindex="-1">1. 订阅 CRUD ✅ <a class="header-anchor" href="#_1-订阅-crud-✅" aria-label="Permalink to &quot;1. 订阅 CRUD ✅&quot;">​</a></h3><ul><li>创建/编辑/删除/重置均正常。删除时 <code>respondAfterSubPush</code> 触发 <code>applyKernelsForInbounds</code>，凭据从节点移除（符合手册&quot;面板会把它的凭据从节点上删掉&quot;）。</li><li>重置链接生成新 UUID/密码，旧链接失效（<code>subscriptionReset</code>）。</li></ul><h3 id="_2-处理流水线-✅" tabindex="-1">2. 处理流水线 ✅ <a class="header-anchor" href="#_2-处理流水线-✅" aria-label="Permalink to &quot;2. 处理流水线 ✅&quot;">​</a></h3><ul><li><code>ApplySubOptions</code> (<code>sub_options.go:219</code>) 顺序：Filter → Rename → Flag → Dedupe → Prefix → Sort → Script → markChain。</li><li>脚本在 <code>markChain</code> 之前执行，链式匹配能看到脚本改名后的名字（符合手册&quot;匹配的是改名后的名字，也认原名&quot;）。</li><li>去重键为 host|port|protocol（手册&quot;地址、端口、协议都相同的只保留第一个&quot;）✅。</li></ul><h3 id="_3-订阅规则-10-规则组-✅" tabindex="-1">3. 订阅规则（10 规则组）✅ <a class="header-anchor" href="#_3-订阅规则-10-规则组-✅" aria-label="Permalink to &quot;3. 订阅规则（10 规则组）✅&quot;">​</a></h3><ul><li><code>ruleGroupDefs</code> 共 10 组：ads/ai/youtube/netflix/media/telegram/google/microsoft/apple/games，与手册一致。</li><li><code>NormalizeRuleGroups</code> 按展示顺序排列，非法 key 过滤。</li><li>Clash 输出含 <code>proxy-groups</code> + <code>rules</code>；sing-box 含路由规则；Loon/QX/Shadowrocket 输出完整配置（非纯节点列表）✅。</li></ul><h3 id="_4-订阅脚本-goja-沙箱-✅" tabindex="-1">4. 订阅脚本（goja 沙箱）✅ <a class="header-anchor" href="#_4-订阅脚本-goja-沙箱-✅" aria-label="Permalink to &quot;4. 订阅脚本（goja 沙箱）✅&quot;">​</a></h3><ul><li>1 秒超时（<code>scriptTimeout</code>），20000 字符上限（<code>MaxScriptLength</code>）。</li><li>仅 <code>name</code> 变更被采纳，其他字段只读（<code>sub_script.go:110-113</code>）。</li><li>裸 goja VM，无网络/文件/定时器；<code>console.log</code> 已 stub。</li><li>脚本失败不影响其他步骤（<code>ApplySubOptions</code> 忽略错误，符合手册）。</li></ul><h3 id="_5-链式代理-✅" tabindex="-1">5. 链式代理 ✅ <a class="header-anchor" href="#_5-链式代理-✅" aria-label="Permalink to &quot;5. 链式代理 ✅&quot;">​</a></h3><ul><li><code>chainMatchers</code>：多选名称时按 <code>Original</code> 精确匹配；表达式时匹配 <code>Name</code> 或 <code>Original</code>（手册&quot;匹配的是改名后的名字，也认原名&quot;）。</li><li>两项都填且都匹配才生效，否则清空 <code>ChainRole</code>（手册&quot;两项都填且都匹配到节点才生效&quot;）。</li><li>Loon/QX 输出不含链式代理参数（<code>loonConfig</code>/<code>qxConfig</code> 未引用 <code>ChainRole</code>），落地节点为直连（手册&quot;✗&quot;）✅。</li><li>Base64 通用链接无法表达链式（<code>share.go</code> 的 base64 路径未处理 chain）✅。</li></ul><h3 id="_6-订阅签名-✅" tabindex="-1">6. 订阅签名 ✅ <a class="header-anchor" href="#_6-订阅签名-✅" aria-label="Permalink to &quot;6. 订阅签名 ✅&quot;">​</a></h3><ul><li>HMAC-SHA256，<code>subtle.ConstantTimeCompare</code> 防时序攻击。</li><li><code>?user=</code> 无 sig 时 fail-closed 403（<code>kernel_relay.go:555</code>）。</li></ul><h3 id="_7-subscription-userinfo-✅" tabindex="-1">7. Subscription-Userinfo ✅ <a class="header-anchor" href="#_7-subscription-userinfo-✅" aria-label="Permalink to &quot;7. Subscription-Userinfo ✅&quot;">​</a></h3><ul><li>非分享订阅的 <code>total</code> 已修复（1.0.3，<code>kernel_relay.go:635</code> 的 <code>total = sub.TrafficLimit</code>）。</li><li>格式 <code>upload=%d; download=%d; total=%d; expire=%d</code> 符合 Clash 规范。</li></ul><h3 id="_8-到期-流量-每月重置-✅" tabindex="-1">8. 到期/流量/每月重置 ✅ <a class="header-anchor" href="#_8-到期-流量-每月重置-✅" aria-label="Permalink to &quot;8. 到期/流量/每月重置 ✅&quot;">​</a></h3><ul><li><code>syncSubscriptions</code> 后台循环处理到期、超限、每月重置，触发 kernel 推送移除凭据。</li><li><code>lastResetAt</code> 正确处理月末边界（如 2 月 30 日→28 日）。</li><li>90% 和用完时推送通知（<code>notify</code> 调用点存在）。</li></ul><h3 id="_9-我的订阅-用户端-✅" tabindex="-1">9. 我的订阅（用户端）✅ <a class="header-anchor" href="#_9-我的订阅-用户端-✅" aria-label="Permalink to &quot;9. 我的订阅（用户端）✅&quot;">​</a></h3><ul><li><code>getMyInbounds</code> 按 <code>Enabled != 1</code> 过滤（F-AUDIT-001 已修复）。</li><li>按中转级别过滤（<code>allowedRelays</code> map）。</li></ul><h3 id="_10-p0-1-p0-2-h-001-修复验证-✅" tabindex="-1">10. P0-1/P0-2/H-001 修复验证 ✅ <a class="header-anchor" href="#_10-p0-1-p0-2-h-001-修复验证-✅" aria-label="Permalink to &quot;10. P0-1/P0-2/H-001 修复验证 ✅&quot;">​</a></h3><ul><li><code>subPipeline</code> 18 字段齐全，<code>options()</code> 映射完整。</li><li>订阅列表 API 返回 <code>ruleGroups</code>。</li><li><code>parsePipeline</code> 新字段 nil→[] 默认值已补（1.0.7）。</li></ul><h2 id="未能验证" tabindex="-1">未能验证 <a class="header-anchor" href="#未能验证" aria-label="Permalink to &quot;未能验证&quot;">​</a></h2><ul><li>浏览器实际操作（无浏览器环境）：订阅编辑页交互、&quot;看看结果&quot;预览、客户端一键导入（<code>clash://</code> 等 scheme）。</li><li>大订阅性能（千节点级渲染耗时）。</li><li>订阅源自动更新（定时任务触发）。</li></ul><h2 id="修复建议顺序" tabindex="-1">修复建议顺序 <a class="header-anchor" href="#修复建议顺序" aria-label="Permalink to &quot;修复建议顺序&quot;">​</a></h2><ol><li>O4-001（P1）：preview 返回 <code>SubScriptError</code>，前端显示脚本错误。</li><li>O4-002（P2）：更新测试期望 SNI 为 <code>www.amd.com</code>。</li><li>O4-003（P2）：HMAC 绑定 token。</li><li>O4-004/O4-005（P3）：文档与数据卫生。</li></ol>',44)])])}const g=e(t,[["render",r]]);export{p as __pageData,g as default};
